contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, bool callRely) public {
        bool wasWard = c.wards(user) == 1;
        bool reverted;
        if (callRely) {
            try c.rely(user) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        bool afterWard = c.wards(user) == 1;

        assert(callRely ? (!reverted && afterWard) : (afterWard == wasWard));
    }

    receive() external payable {}
}

