contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user) public {
        require(user != address(this));
        require(c.wards(user) == 0);

        uint256 beforeUserWards = c.wards(user);
        uint256 beforeSenderWards = c.wards(address(this));

        bool relyReverted;
        try c.rely(user) { relyReverted = false; } catch { relyReverted = true; }

        bool denyReverted;
        try c.deny(user) { denyReverted = false; } catch { denyReverted = true; }

        bool fileReverted;
        try c.file("investmentManager", user) { fileReverted = false; } catch { fileReverted = true; }

        bool updatePriceReverted;
        try c.updatePrice(uint128(uint256(uint160(user)))) { updatePriceReverted = false; } catch { updatePriceReverted = true; }

        bool mintReverted;
        try c.mint(user, 1) { mintReverted = false; } catch { mintReverted = true; }

        bool burnReverted;
        try c.burn(user, 1) { burnReverted = false; } catch { burnReverted = true; }

        assert(
            relyReverted && denyReverted && fileReverted && updatePriceReverted && mintReverted && burnReverted
                && c.wards(user) == beforeUserWards
                && c.wards(address(this)) == beforeSenderWards
                && c.wards(address(this)) == 1
        );
    }

    receive() external payable {}
}

