contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, address to, uint256 value) public payable {
        // Ensure a transferFrom cannot trivially succeed: use a spender that is not
        // the owner of the shares, and require the spender has a balance to send.
        require(spender != to, "spender == to");

        // Some initial approval from this test contract (which uses its own share
        // balance? no -- C.transferFrom forwards to share.transferFrom with msg.sender,
        // so the relevant owner is this contract's address). We cannot mint shares
        // to ourselves, but we can read balances and compare them.

        // Set up: this test contract approves itself? C.transferFrom calls
        // share.transferFrom(msg.sender=this, to, value) via the appended msg.sender.
        // So the "from" seen by the share token is the test contract address.
        // The test contract's share balance is some value `bal`.

        // Read spender's balance before (spender must be the from-address?).
        // Actually C.transferFrom overlays msg.sender (the test contract) as the last
        // 20 bytes appended to msg.data, i.e. it calls share.transferFrom(from=this,
        // to, value, sender=this). So the spent balance belongs to address(this).
        uint256 thisBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);

        bool reverted;
        bool ret;
        try c.transferFrom(spender, to, value) returns (bool r) {
            ret = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 thisAfter = c.balanceOf(address(this));
            uint256 toAfter = c.balanceOf(to);
            // Rule: a successful transferFrom returns true and moves `value` from
            // this contract to `to` (unless from == to, which we excluded).
            assert(ret && thisAfter + value == thisBefore && toAfter == toBefore + value);
        } else {
            // Rule: if it reverts then the pre-state must have been insufficient
            // (balance or allowance), i.e. a revert is justified.
            assert(value > thisBefore || c.allowance(address(this), spender) < value);
        }
    }

    receive() external payable {}
}

