    function run(address to, uint256 value) public payable {
        require(to != address(this), "self-transfer excluded");

        uint256 thisBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(to);
        uint256 approved = c.allowance(address(this), address(this));

        bool reverted;
        try c.transferFrom(to, to, value) returns (bool r) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 thisAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(to);

        assert(
            (!reverted && thisAfter + value == thisBefore && toAfter == toBefore + value)
                || (reverted && (value > thisBefore || approved < value))
        );
    }

