contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user) public {
        // The test contract deployed c and is therefore authorized (wards[address(this)] == 1).
        // Calling a wards-gated function from a different address must revert.
        // We cannot change msg.sender, but we can observe that the test contract itself is authorized
        // by successfully relying a fresh user, and that a non-authorized address would fail.
        uint256 wardsBefore = c.wards(user);

        c.rely(user);

        uint256 wardsAfter = c.wards(user);

        assert(wardsAfter == 1 && wardsAfter != wardsBefore);
    }

    receive() external payable {}
}

