contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address user, bool doRely, bool doDeny, uint256 x) public payable {
        require(user != address(0));

        // Baseline: initially the test contract (as deployer) is the only ward.
        uint256 wardOfUserBefore = c.wards(user);
        uint256 wardOfThisBefore = c.wards(address(this));
        require(wardOfThisBefore == 1, "deployer must be ward");

        if (doRely) {
            // Only the deployer (this contract) is authorized; rely can succeed only when authorized.
            bool relyReverted;
            try c.rely(user) { relyReverted = false; } catch { relyReverted = true; }
            if (!relyReverted) {
                assert(c.wards(user) == 1);
            } else {
                assert(c.wards(user) == wardOfUserBefore);
            }
        }

        if (doDeny) {
            bool denyReverted;
            try c.deny(user) { denyReverted = false; } catch { denyReverted = true; }
            if (!denyReverted) {
                assert(c.wards(user) == 0);
            } else {
                // If we didn't rely first, user may have been 0 already; if we did rely successfully, user is 1.
                if (doRely) {
                    // After a successful rely, the user must be 1; deny only reverts if unauthorized, but we are authorized.
                    assert(c.wards(user) == 0);
                } else {
                    assert(c.wards(user) == wardOfUserBefore);
                }
            }
        }

        // Final general rule: the contract's contract-level state is consistent: wards(this) == 1 always after run.
        assert(c.wards(address(this)) == 1);
    }

    receive() external payable {}
}

