        c = _c;
    }

    function run(address caller, uint128 newPrice) public {
        require(caller != address(this), "caller is the contract itself");

        bool callerIsWard = c.wards(caller) == 1;
        uint128 beforePrice = c.latestPrice();

        bool reverted;
        if (callerIsWard) {
            try c.updatePrice(newPrice) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.updatePrice(newPrice) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert(
            callerIsWard
                ? (!reverted && c.latestPrice() == newPrice)
                : (reverted && c.latestPrice() == beforePrice)
        );
    }
}

