contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, bool doRely, bool doDeny, address finalUser) public {
        require(user != address(0));
        require(finalUser != address(0));
        require(address(this) == c.wards(address(this)) == 1 ? true : c.wards(address(this)) == 1);

        uint256 beforeWardsUser = c.wards(user);
        uint256 beforeWardsFinalUser = c.wards(finalUser);

        bool relyReverted;
        if (doRely) {
            try c.rely(user) {
                relyReverted = false;
            } catch {
                relyReverted = true;
            }
        } else {
            relyReverted = false;
        }

        bool denyReverted;
        if (doDeny) {
            try c.deny(user) {
                denyReverted = false;
            } catch {
                denyReverted = true;
            }
        } else {
            denyReverted = false;
        }

        bool finalReverted;
        try c.rely(finalUser) {
            finalReverted = false;
        } catch {
            finalReverted = true;
        }

        if (!relyReverted) {
            assert(c.wards(user) == 1 || (doDeny && !denyReverted && c.wards(user) == 0));
        }
        if (!denyReverted) {
            assert(c.wards(user) == 0 || (doRely && !relyReverted && false));
        }

        if (!finalReverted) {
            assert(c.wards(finalUser) == 1);
        } else {
            assert(c.wards(finalUser) == beforeWardsFinalUser);
        }

        assert(c.wards(address(this)) == 1);
    }

    receive() external payable {}
}

