contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 assets, uint256 shares, address receiver, address owner, address caller) public payable {
        require(caller != owner, "need distinct caller and owner");

        bool depositReverted;
        bool withdrawReverted;

        // For a caller that is not the owner, deposit(receiver) must revert
        // because of the withApproval modifier. We cannot change msg.sender,
        // so the only way to exercise this is to call as address(this) and
        // use a receiver that is not address(this).
        if (receiver != address(this)) {
            try c.deposit(assets, receiver) returns (uint256) {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
        }

        // Similarly, withdraw(assets, receiver, owner) must revert when the
        // caller (address(this)) is not the owner.
        if (owner != address(this)) {
            try c.withdraw(assets, receiver, owner) returns (uint256) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        }

        // The general rule: whenever the caller is not the owner, the
        // withApproval-gated entrypoints must revert. We encode the two
        // observable cases we can reach from this test contract.
        assert(
            (receiver == address(this) || depositReverted) &&
            (owner == address(this) || withdrawReverted)
        );
    }
}

