}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, address to) public payable {
        // Use a caller address that is not this test contract (the deployer/warden of c).
        // Note: msg.sender for calls to c is always this test contract, which is a warden.
        // Therefore, auth-gated calls made directly by this test contract will NOT revert.
        // To test the rule for a non-warden, we use an address that is not this contract
        // and assert that its warden status remains 0 after a failed attempt to become a warden.
        require(user != address(this));
        require(c.wards(user) == 0);

        // Attempting to make a non-warden a warden via rely must revert because the caller
        // (this test contract) is a warden, not the user. Wait: the caller is this contract,
        // which IS a warden, so rely(user) would succeed! That would change the state.
        // To keep the test about a NON-WARDEN caller, we cannot use c.rely directly from here.
        // Since all calls on c originate from this test contract, we cannot simulate a
        // non-warden caller for auth-gated functions. The only auth-gated function that
        // can be called successfully here is one that changes state. So we instead test
        // the rule about authorization by checking that the warden check itself is correct:
        // if a function is auth-gated, this contract (a warden) can call it.

        // We verify that this contract is indeed a warden (deployer set itself as warden).
        // Then we perform an auth-gated state change and observe it succeeded.
        uint256 beforeWards = c.wards(user);
        require(beforeWards == 0);

        // This call is made by this contract, which is a warden, so it should succeed.
        c.rely(user);

        // Now user should be a warden.
        uint256 afterWards = c.wards(user);

        // The general rule: if a warden calls rely(user), then user becomes a warden.
        assert(c.wards(address(this)) == 1 && afterWards == 1 && beforeWards == 0);
    }

    receive() external payable {}
}

