        require(caller != address(this), "caller is test");

        uint256 beforeWard = c.wards(user);

        bool relyReverted;
        try c.rely(user) {
            relyReverted = false;
        } catch {
            relyReverted = true;
        }

        uint256 afterRely = c.wards(user);

        bool denyReverted;
        try c.deny(user) {
            denyReverted = false;
        } catch {
            denyReverted = true;
        }

        uint256 afterDeny = c.wards(user);

        if (relyReverted) {
            assert(afterRely == beforeWard && afterDeny == beforeWard);
        } else {
            assert(afterRely == 1 && afterDeny == 0);
        }
    }
}

